"use strict";(self.webpackChunkwhimsylabs_website=self.webpackChunkwhimsylabs_website||[]).push([[4017],{4017(e,i,n){n.d(i,{content:()=>r,description:()=>o,keywords:()=>s,title:()=>t});n(5043);var a=n(579);const t="WhimsyLabs Story: From Startup to BETT 2025 Winner",o="How Whimsylabs, founded by Marisa French, is addressing STEM challenges with fully simulated labs, impactful partnerships, and award-winning innovation.",s=["virtual laboratory history","BETT 2025 winner","STEM education innovation","COVID-19 education solutions","proprietary physics engine","WhimsyLabs founding story","Marisa French founder","virtual lab development","EdTech startup journey"],r=(0,a.jsxs)("div",{children:[(0,a.jsxs)("p",{children:["In 2023, the UK plummeted to 15th place in global science rankings (",(0,a.jsx)("a",{href:"https://www.oecd.org/publication/pisa-2022-results/",target:"_blank",rel:"noopener noreferrer",children:"OECD, 2023"}),"), while the pandemic left millions of students worldwide without hands-on lab access for years (",(0,a.jsx)("a",{href:"https://www.iza.org/publications/dp/13820/covid-19-and-educational-inequality-how-school-closures-affect-low-and-high-achieving-students",target:"_blank",rel:"noopener noreferrer",children:"Grewenig et al., 2021"}),"). This perfect storm of declining STEM performance and infrastructure loss catalyzed the creation of Whimsylabs in 2020, founded by Marisa French during her Physics PhD. For Marisa, this crisis felt deeply personal; she had been inspired to pursue science through the hands-on practicals she experienced in secondary school, opportunities that were now disappearing for a new generation."]}),(0,a.jsx)("h2",{children:"How Did Whimsylabs Begin?"}),(0,a.jsxs)("p",{children:["Driven by a desire to create meaningful change, Marisa leveraged her simulation and gaming skills to develop a fully simulated sandbox virtual laboratory. Research demonstrates that simulation-based learning environments can significantly improve student engagement and learning outcomes, particularly in STEM fields where hands-on experimentation is crucial (",(0,a.jsx)("a",{href:"https://www.learntechlib.org/p/48419/",target:"_blank",rel:"noopener noreferrer",children:"Rutten et al., 2012"}),"). This lab was designed to be a safe, accessible, and engaging environment for hands-on learning, without the risks or costs associated with traditional labs. The goal was simple; make a virtual lab that fully captured the fun that she experienced in her school labs, and that could be used by anyone, anywhere, at any time."]}),(0,a.jsx)("img",{src:"/images/oldLab.png",alt:"First mockup lab",className:"rounded shadow center limited-size"}),(0,a.jsx)("p",{className:"caption",children:"The first lab mockup: A simple prototype to conceptualize the vision for Whimsylabs."}),(0,a.jsxs)("p",{children:["The journey began modestly with a rudimentary lab mockup that served to test initial coding ideas. Right from the start the dream of a unified virtual lab was clear, but the path to realizing it was less so. With academic simulations as a foundation, the first lab iteration was a simple prototype that laid the groundwork to test ideas and refine the vision. However, as most academic simulations use supercomputers, and take months to run (",(0,a.jsx)("a",{href:"https://www.sciencedirect.com/book/9781558609334/the-grid-2",target:"_blank",rel:"noopener noreferrer",children:"Foster & Kesselman, 2003"}),"), the challenge was to make the simulations run in real-time on a bespoke VR platform."]}),(0,a.jsxs)("p",{children:["Most of the work was done to refine these equations down to run in real time, while still producing realistic results. The first lab was purely a proof of concept, showing that the simulations could be run in real time, and that they could be interacted with in a meaningful way. Studies in computational physics education highlight the importance of real-time interaction for conceptual understanding, as immediate feedback helps students connect theoretical concepts with observable phenomena (",(0,a.jsx)("a",{href:"https://www.nature.com/articles/nphys293",target:"_blank",rel:"noopener noreferrer",children:"Wieman & Perkins, 2006"}),")."]}),(0,a.jsx)("h2",{children:"What Breakthrough Led to University Recognition?"}),(0,a.jsx)("p",{children:"Around this time Whimsylabs caught the attention of the University of Edinburgh due to our breakthrough work in simulations and ambitious impact driven goals, securing places in their prestigious incubator programs and going on to win the Summer Accelerator. From these victories and recognitions, we were able to secure our first bout of funding to build a bespoke VR/web combo platform, and bring on our second founder to help build the lab; a Chemist PhD with years of experience in education and training for the chemical industry."}),(0,a.jsx)("img",{src:"/images/testLab.png",alt:"Second tech test lab",className:"rounded shadow center limited-size"}),(0,a.jsx)("p",{className:"caption",children:"The second lab: A testing ground for advanced simulation technologies."}),(0,a.jsxs)("p",{children:["The second lab was built to see how we could make the lab feel more like a real lab, and less like a video game. This was first time we had to consider how the lab would be used in a real educational setting to teach the motions and actions of a lab. This phenomenology of the lab revealed itself to be crucial for students to begin to build the muscle memory needed to perform these procedures in real life, with things like liquid physics and realistic physical interactions needed to capture feeling of being in a lab. Research in embodied cognition demonstrates that physical movements and gestures significantly enhance learning and retention in scientific contexts (",(0,a.jsx)("a",{href:"https://www.frontiersin.org/articles/10.3389/fpsyg.2019.00625/full",target:"_blank",rel:"noopener noreferrer",children:"Macedonia, 2019"}),")."]}),(0,a.jsx)("p",{children:"The second lab was a success, and we were able to reach out to schools to test the lab in a real educational setting. The feedback was overwhelmingly positive, with students and teachers alike praising the lab for its realism and ease of use. This was a critical step in the development of the lab, as it showed that the lab could be used in a real educational setting, and that it could be a valuable tool for teaching and learning. There was just one issue: the lab was ugly."}),(0,a.jsx)("h2",{children:"Why Did We Redesign the Lab from Scratch?"}),(0,a.jsx)("img",{src:"/images/finalLab.png",alt:"Final lab design",className:"rounded shadow center limited-size"}),(0,a.jsx)("p",{className:"caption",children:"The final lab: A blend of cutting-edge technology and an inviting design that stands out."}),(0,a.jsxs)("p",{children:["With this in mind, we set out to completely redesign the lab from scratch. However, due to the limited power of VR headsets and the processing cost of the advanced simulations, there was little room to reflect high fidelity realism. Another consideration was the broad range of ages that would be using the lab, from 5 to 18+, and the need to make the lab accessible to all of them. The choice of direction was difficult, but in the end we were guided by one of our original desires that the lab is a place of wonder and exploration, and that it should be a place that students want to come back to. Research in educational psychology emphasizes the importance of intrinsic motivation and curiosity-driven learning in STEM education (",(0,a.jsx)("a",{href:"https://www.tandfonline.com/doi/abs/10.1207/S15327965PLI1104_01",target:"_blank",rel:"noopener noreferrer",children:"Deci & Ryan, 2000"}),"). It was around this time where we settled on our Whimsycat as our logo and mascot, an icon unlike any other in the virtual lab space, encapsulating the curiosity and wonder that we wanted to inspire in our students."]}),(0,a.jsx)("p",{children:"The final lab design was a blend of cutting-edge technology and an inviting design that stands out in the crowded edtech space. This lab, our current flagship lab was now a fully realized virtual environment that offered a wide range of experiments and simulations, across Chemistry, Physics and Biology. Using this lab we were able to enter the prestigious Converge Challenge, a competition for the best new businesses in Scotland, and secure a place in the final under the Create Change category, where we placed Second out of all businesses in Scotland."}),(0,a.jsx)("h2",{children:"How Did We Win BETT 2025 Recognition?"}),(0,a.jsx)("p",{children:"Through our victory at Converge, we secured the funds to attend BETT UK and take our innovations to a global stage. The feedback from students and educators alike was overwhelmingly positive, with many highlighting how the platform transforms STEM education. Additionally, Whimsylabs' innovative approach had not gone unnoticed. The platform was recognized by the Epping Forest Schools Partnership Trust as part of the Kids Judge Bett, where pupils nominated Whimsylabs for their use of virtual labs to teach students about laboratory environments, while also providing a powerful tool for sustainability. This acknowledgment highlights the power in our mission to inspire the next generation of STEM leaders."}),(0,a.jsx)("p",{children:"While Whimsylabs has been quietly developing its technology for the past few years, only whispered amongst a few piloting schools, we are now ready to make noise and be loud about our groundbreaking solution. With a strong foundation, a growing team, and a proven track record of innovation, Whimsylabs is poised to transform science education and inspire the next generation of STEM leaders while staying true to our core values. To provide a sandbox laboratory that captures the physicality of performing labs, to capture the fun and wonder of science, and to democratize access to premium science education technology for all institutions worldwide."}),(0,a.jsx)("h2",{children:"Related Articles"}),(0,a.jsxs)("ul",{children:[(0,a.jsx)("li",{children:(0,a.jsx)("a",{href:"/blog/whimsycat-ai-tutor-transforming-science-education",children:"Meet WhimsyCat: Our AI Innovation in Science Education"})}),(0,a.jsx)("li",{children:(0,a.jsx)("a",{href:"/blog/physicality-in-virtual-labs",children:"The Physicality Breakthrough: How We Made Virtual Labs Feel Real"})}),(0,a.jsx)("li",{children:(0,a.jsx)("a",{href:"/blog/sandbox-learning-revolution-stem-education",children:"Our Sandbox Learning Philosophy: Freedom to Fail and Explore"})}),(0,a.jsx)("li",{children:(0,a.jsx)("a",{href:"/blog/ai-powered-virtual-labs-solving-education-crisis",children:"How Our Platform Addresses the Global Science Education Crisis"})})]}),(0,a.jsxs)("div",{className:"references-section",children:[(0,a.jsx)("h3",{children:"References"}),(0,a.jsxs)("ul",{className:"references-list",children:[(0,a.jsx)("li",{children:'Deci, E. L., & Ryan, R. M. (2000). The "what" and "why" of goal pursuits: Human needs and the self-determination of behavior. *Psychological Inquiry, 11*(4), 227-268.'},"ref-1"),(0,a.jsx)("li",{children:"Foster, I., & Kesselman, C. (Eds.). (2003). *The grid: blueprint for a new computing infrastructure*. Morgan Kaufmann."},"ref-2"),(0,a.jsx)("li",{children:"Grewenig, E., Lergetporer, P., Werner, K., Woessmann, L., & Zierow, L. (2021). COVID-19 and educational inequality: How school closures affect low- and high-achieving students. *European Economic Review, 140*, 103920."},"ref-3"),(0,a.jsx)("li",{children:'Macedonia, M. (2019). The "what," "how," and "why" of using gestures in the foreign language classroom to enhance learning. *Frontiers in Psychology, 10*, 1142.'},"ref-4"),(0,a.jsx)("li",{children:"OECD. (2023). *PISA 2022 Results (Volume I): The State of Learning and Equity in Education*. OECD Publishing."},"ref-5"),(0,a.jsx)("li",{children:"Rutten, N., van Joolingen, W. R., & van der Veen, J. T. (2012). The learning effects of computer simulations in science education. *Computers & Education, 58*(1), 136-153."},"ref-6"),(0,a.jsx)("li",{children:"Wieman, C. E., & Perkins, K. K. (2006). A powerful tool for teaching science. *Nature Physics, 2*(5), 290-292."},"ref-7")]})]})]})}}]);
